import EditMaterial from "@/components/MaterialManagement/Popups/EditMaterial.vue";
import DeleteMaterial from "@/components/MaterialManagement/Popups/DeleteMaterial.vue";
import { create_list_edit_delete_material } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
import CreateMaterial from "@/components/MaterialManagement/Popups/CreateMaterial.vue";
export default {
  components: {
    SnackBar,
    EditMaterial,
    DeleteMaterial,
    CreateMaterial
  },
  data() {
    return {
      materialHeaders: [{
        text: "Materials",
        value: "material_name",
        sortable: false
      }, {
        text: "Units",
        value: "materialUnitNames",
        sortable: false
      }, {
        text: "Supplier",
        value: "suppliers",
        sortable: false
      }, {
        text: "Action",
        value: "actions",
        sortable: false
      }],
      fixed: true,
      tableData: [],
      tableLoading: false,
      componentCheck: 0,
      SnackBarComponent: {},
      materialcreation: false,
      materialedition: false,
      rowInfo: {},
      materialdeletion: false
    };
  },
  created() {
    this.fetch_materials();
  },
  methods: {
    create_material() {
      this.componentCheck = 1;
      this.materialcreation = true;
    },
    edit_material(value) {
      this.rowInfo = value;
      this.componentCheck = 2;
      this.materialedition = true;
    },
    open_deletedailog(value) {
      this.rowInfo = value;
      this.componentCheck = 3;
      this.materialdeletion = true;
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.tableData = [];
      this.materialedition = false;
      this.materialdeletion = false;
      this.materialcreation = false;
      this.fetch_materials();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async fetch_materials() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_list_edit_delete_material, {
          input: {
            action_type: "LIST_MATERIAL",
            organization_id: data.organization.organization_id
          }
          // product_name: "",
        }));
        this.tableLoading = false;
        var response = JSON.parse(result.data.create_list_edit_delete_material);
        if (response.Status == "SUCCESS") {
          this.tableLoading = false;
          this.tableData = response.data;
        } else {
          this.tableLoading = false;
          this.tableData = [];
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
